    static func decrypt(_ mod: ModType) throws -> Data {
        guard let encoded = payloads[mod], let combined = Data(base64Encoded: encoded) else {
            throw PayloadError.unavailable
        }
        guard combined.count > 12 else { throw PayloadError.invalidPayload }
        let nonce = combined.prefix(12)
        let ciphertextAndTag = combined.dropFirst(12)
        let payloadKey: String
        switch mod {
        case .hsAlto: payloadKey = "hsAlto"
        case .hsPescoco: payloadKey = "hsPescoco"
        case .hsPeito: payloadKey = "hsPeito"
        case .hologramaArmas: throw PayloadError.unavailable
        case .texturaAlok: payloadKey = "texturaAlok"
        }
        let aad = Data("MenagerFF.payload.v2:\(payloadKey)".utf8)
        do {
            let sealed = try AES.GCM.SealedBox(
                nonce: AES.GCM.Nonce(data: Data(nonce)),
                ciphertext: Data(ciphertextAndTag.dropLast(16)),
                tag: Data(ciphertextAndTag.suffix(16))
            )
            return try AES.GCM.open(sealed, using: key, authenticating: aad)
        } catch {
            throw PayloadError.decryptionFailed
        }
    }
